MATCH (accident:FlightAccident)
WHERE accident.name IN ['Tatarstan Airlines Flight 363', 'Mandala Airlines Flight 091']
RETURN accident.name AS accident_name, accident.number_of_injuries AS number_of_injuries ORDER BY accident.name;

MATCH (m:AircraftModel)
WHERE m.name IN ['Boeing 720', 'DC-9']
  AND m.first_flight IS NOT NULL
RETURN m.name AS aircraft, m.first_flight AS first_flight
ORDER BY m.first_flight DESC
LIMIT 1

